#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────


# Homeport's signing keys (docs/RELEASING.md > Signing keys). Run from anywhere:
#
#   scripts/setup-signing.sh
#
# Creates the two keys releases need, once (or again, to replace them):
# - an RSA 4096 OpenPGP key, no expiry, that signs the APT and RPM repositories
#   and every .rpm. Its public half is packaging/linux/homeport.asc.
# - a minisign key that signs every update; installed copies only install
#   updates signed with it. Its public half is tauri.conf.json > plugins >
#   updater > pubkey.
# The private halves go into GitHub secrets and an offline backup, never git.

REPO_ROOT=$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)
PUBLIC_KEY_FILE="$REPO_ROOT/packaging/linux/homeport.asc"
TAURI_CONF="$REPO_ROOT/src-tauri/tauri.conf.json"
ENV_FILE=/dev/null # nothing here belongs in a .env file

run_wizard() {

TOTAL_STAGES=8
cd "$REPO_ROOT"

banner "Homeport signing keys"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Check the tools"
say "This creates the package and updater signing keys, stores the private"
say "halves as GitHub secrets and in a backup folder, and commits the public halves."
missing=()
for tool in gpg bun gh git; do command -v "$tool" >/dev/null 2>&1 || missing+=("$tool"); done
if (( ${#missing[@]} )); then
  warn "missing: ${missing[*]}. Install them and run this again."
  exit 1
fi
if ! gh auth status >/dev/null 2>&1; then
  warn "gh isn't signed in. Run 'gh auth login' first, so the secrets can be set."
  exit 1
fi
step "gpg, bun, gh and git are ready; gh is signed in."
if [[ -f "$PUBLIC_KEY_FILE" ]] || grep -q '"pubkey": "[^"]' "$TAURI_CONF"; then
  warn "Signing keys are already committed. New keys REPLACE them:"
  note "  - Installed copies only accept updates signed with the updater key"
  note "    built into them, so they will stop updating until reinstalled by hand."
  note "  - Linux users' apt/dnf/zypper keep the old repository key until their"
  note "    package refreshes it (the .deb does on upgrade) or they re-run the setup."
  confirm "Replace the existing keys anyway?" || exit 1
fi
pause

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Name the package key"
say "The OpenPGP key carries a name and email, shown by apt, dnf and gpg."
say "It's public: anyone who checks the key sees it."
ask KEY_NAME "Name [Homeport Packages]:"
KEY_NAME=${KEY_NAME:-Homeport Packages}
ask KEY_EMAIL "Email:"
[[ "$KEY_EMAIL" == *@* ]] || { warn "that doesn't look like an email address"; exit 1; }
KEY_UID="$KEY_NAME <$KEY_EMAIL>"
step "The key will be: $KEY_UID"
pause

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Choose where the backup goes"
say "The private keys, their passphrases and the revocation certificate are"
say "written to a folder only you can read. You'll move it offline in stage 7."
default_backup="$HOME/homeport-signing-keys-$(date +%Y%m%d)"
ask BACKUP_DIR "Backup folder [$default_backup]:"
BACKUP_DIR=${BACKUP_DIR:-$default_backup}
if [[ -e "$BACKUP_DIR" ]] && [[ -n "$(ls -A "$BACKUP_DIR" 2>/dev/null)" ]]; then
  warn "$BACKUP_DIR isn't empty; pick a new folder so no backup is overwritten."
  exit 1
fi
(umask 077 && mkdir -p "$BACKUP_DIR")
step "Backups go to $BACKUP_DIR"
pause

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Create the package signing key"
say "Pick a passphrase for the OpenPGP key (CI gets it as a secret, so make it long)."
while :; do
  ask_secret GPG_PASSPHRASE "Passphrase:"
  ask_secret GPG_PASSPHRASE_AGAIN "Again:"
  [[ -n "$GPG_PASSPHRASE" && "$GPG_PASSPHRASE" == "$GPG_PASSPHRASE_AGAIN" ]] && break
  warn "empty, or the two didn't match. Try again."
done
GNUPGHOME=$(mktemp -d)
export GNUPGHOME
trap 'gpgconf --kill gpg-agent 2>/dev/null; rm -rf "$GNUPGHOME"' EXIT
gpg_batch() { gpg --batch --pinentry-mode loopback --passphrase-fd 0 "$@" <<<"$GPG_PASSPHRASE"; }
say "Generating an RSA 4096 key (this can take a minute)…"
gpg_batch --quiet --quick-gen-key "$KEY_UID" rsa4096 sign never
FPR=$(gpg --batch --with-colons --list-secret-keys | awk -F: '/^fpr/ { print $10; exit }')
gpg --batch --armor --export "$FPR" >"$PUBLIC_KEY_FILE"
gpg_batch --armor --export-secret-keys "$FPR" >"$BACKUP_DIR/homeport-packages-secret.asc"
cp "$GNUPGHOME/openpgp-revocs.d/$FPR.rev" "$BACKUP_DIR/homeport-packages-revocation.rev"
printf '%s\n' "$GPG_PASSPHRASE" >"$BACKUP_DIR/homeport-packages-passphrase.txt"
step "Key $FPR"
step "Public key → packaging/linux/homeport.asc"
step "Private key, passphrase and revocation certificate → $BACKUP_DIR"
pause

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Create the updater signing key"
say "Pick a passphrase for the updater key (different from the last one)."
while :; do
  ask_secret UPDATER_PASSWORD "Passphrase:"
  ask_secret UPDATER_PASSWORD_AGAIN "Again:"
  [[ -n "$UPDATER_PASSWORD" && "$UPDATER_PASSWORD" == "$UPDATER_PASSWORD_AGAIN" ]] && break
  warn "empty, or the two didn't match. Try again."
done
UPDATER_KEY="$BACKUP_DIR/homeport-updater.key"
bun tauri signer generate --ci -p "$UPDATER_PASSWORD" -w "$UPDATER_KEY" >/dev/null
printf '%s\n' "$UPDATER_PASSWORD" >"$BACKUP_DIR/homeport-updater-passphrase.txt"
UPDATER_PUBKEY=$(<"$UPDATER_KEY.pub")
PUBKEY="$UPDATER_PUBKEY" bun -e '
  const file = process.argv[1];
  const conf = JSON.parse(await Bun.file(file).text());
  conf.plugins.updater.pubkey = process.env.PUBKEY;
  await Bun.write(file, JSON.stringify(conf, null, 2) + "\n");
' "$TAURI_CONF"
bunx prettier --log-level warn --write "$TAURI_CONF"
step "Public key → tauri.conf.json > plugins > updater > pubkey"
step "Private key and passphrase → $BACKUP_DIR"
pause

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Store the private keys as GitHub secrets"
say "The Release workflow signs the .rpm and each update; the Pages workflow"
say "signs the repositories. These four secrets let them:"
note "  PACKAGES_GPG_PRIVATE_KEY, PACKAGES_GPG_PASSPHRASE,"
note "  TAURI_SIGNING_PRIVATE_KEY, TAURI_SIGNING_PRIVATE_KEY_PASSWORD"
if confirm "Set them on $(gh repo view --json nameWithOwner --jq .nameWithOwner) now?"; then
  set_secret PACKAGES_GPG_PRIVATE_KEY "$(<"$BACKUP_DIR/homeport-packages-secret.asc")"
  set_secret PACKAGES_GPG_PASSPHRASE "$GPG_PASSPHRASE"
  set_secret TAURI_SIGNING_PRIVATE_KEY "$(<"$UPDATER_KEY")"
  set_secret TAURI_SIGNING_PRIVATE_KEY_PASSWORD "$UPDATER_PASSWORD"
else
  SKIPPED+=("the four GitHub secrets, from the files in $BACKUP_DIR")
fi
pause

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "Move the backup offline"
say "Without these files no new release can be signed, and updates to installed"
say "copies stop for good. Keep them somewhere offline, such as an encrypted USB"
say "drive or your password manager:"
for file in "$BACKUP_DIR"/*; do note "  $(basename "$file")"; done
note "  (the .rev file revokes the package key if it ever leaks: gpg --import it)"
step "Copy the folder $BACKUP_DIR to your offline storage."
pause "Press Enter once it's copied…"
if confirm "Delete $BACKUP_DIR from this computer now?"; then
  rm -rf "$BACKUP_DIR"
  step "Deleted."
else
  SKIPPED+=("delete $BACKUP_DIR once it's safely stored offline")
fi
pause

# ── 8 ─────────────────────────────────────────────────────────────────────
stage "Commit the public keys"
git --no-pager diff --stat -- "$TAURI_CONF"
git status --short -- "$PUBLIC_KEY_FILE"
if confirm "Commit packaging/linux/homeport.asc and tauri.conf.json?"; then
  git add -- "$PUBLIC_KEY_FILE" "$TAURI_CONF"
  git commit -q -m "build(signing): add the package and updater public keys" \
    -m "Package key: $FPR"
  step "Committed on $(git branch --show-current). Push it before releasing."
else
  SKIPPED+=("commit packaging/linux/homeport.asc and src-tauri/tauri.conf.json")
fi
pause

finish
note "Package key fingerprint: $FPR"
note "Releasing: docs/RELEASING.md"
}

run_wizard "$@"; exit
